# Generated by the MCRI team.
#
# 0022 set the `is_annotated_in_any_gene` default to `length(geneId_ids) > 1`, so variants
# in exactly one gene were flagged as not annotated in any gene and dropped from searches
# that filter on it (gene lists of MAX_XPOS_FILTER_INTERVALS or more, require_any_gene).
# Upstream fixed this in broadinstitute/seqr#5228 (0037_geneIds_bugfix).
#
# This only changes the default, which is evaluated at insert time. Rows already loaded
# keep their value: they must be reloaded (or backfilled as in upstream's 0037).
from django.db import migrations

ALTER_DEFAULT = 'ALTER TABLE `{table}` MODIFY COLUMN `is_annotated_in_any_gene` Bool DEFAULT length(geneId_ids) > {min_genes};'
TABLES = ['GRCh37/SNV_INDEL/entries', 'GRCh38/SNV_INDEL/entries']


class Migration(migrations.Migration):

    dependencies = [
        ('clickhouse_search', '0026_per_assay_gt_stats'),
    ]

    operations = [
        migrations.RunSQL(
            ALTER_DEFAULT.format(table=table, min_genes=0),
            ALTER_DEFAULT.format(table=table, min_genes=1),
            hints={'clickhouse': True},
        )
        for table in TABLES
    ]
